    private const string DocsUrl = "https://code.claude.com/docs/en/settings-reference";

    private static readonly HashSet<string> Documented = new(Keys, StringComparer.Ordinal);

    /// <summary>
    /// The reference entry for a key, or its nearest documented ancestor: a nested key is explained by the section
    /// above it. The anchor is the key lowercased with dots removed, the form the reference uses.
    /// </summary>
    public static string? Url(string key)
    {
        for (var candidate = key; ;)
        {
            if (Documented.Contains(candidate)) return $"{DocsUrl}#{candidate.ToLowerInvariant().Replace(".", "", StringComparison.Ordinal)}";
            var cut = candidate.LastIndexOf('.');
            if (cut == -1) return null;
            candidate = candidate[..cut];
        }
    }
